// ===== TEAMS & VIRTUAL =====
const TEAMS_16=[{name:'Man Utd',short:'MUN'},{name:'Aston Villa',short:'AVL'},{name:'Crystal Palace',short:'CRY'},{name:'Everton',short:'EVE'},{name:'Tottenham',short:'TOT'},{name:'West Ham',short:'WHU'},{name:'Liverpool',short:'LIV'},{name:'Wolves',short:'WOL'},{name:'Arsenal',short:'ARS'},{name:'Chelsea',short:'CHE'},{name:'Brentford',short:'BRE'},{name:'Brighton',short:'BHA'},{name:'Man City',short:'MCI'},{name:'Fulham',short:'FUL'},{name:'Newcastle',short:'NEW'},{name:'Nottm Forest',short:'NFO'}];
function genSched(){let teams=[...TEAMS_16];let rounds=[];let n=teams.length;let fixed=teams[0];let rot=teams.slice(1);for(let r=0;r<n-1;r++){let fixtures=[];let all=[fixed,...rot];for(let i=0;i<n/2;i++){let h=all[i];let a=all[n-1-i];if(r%2===0)fixtures.push({home:h,away:a});else fixtures.push({home:a,away:h});}rot=[rot[rot.length-1],...rot.slice(0,rot.length-1)];rounds.push(fixtures);}return rounds;}
let seasonSchedule=genSched();let season=1,matchday=0;
function getFix(md){let round=seasonSchedule[md%15];return round.map((m,i)=>({...m,id:(md+1)*100000+i*1000+Math.floor(Math.random()*900)}));}
let currentFixtures=getFix(matchday);let nextFixtures=getFix(matchday+1);let liveFixtures=null;let targetScores=null;let virtualPhase='betting';let virtualTimeLeft=120;let pastResults=[];let leagueTable={};
function initTable(){leagueTable={};TEAMS_16.forEach(t=>{leagueTable[t.short]={name:t.name,short:t.short,pld:0,w:0,d:0,l:0,gf:0,ga:0,pts:0};});}initTable();
function updateTable(fix){fix.forEach(f=>{let[hg,ag]=f.score.split('-').map(Number);let ht=leagueTable[f.home.short];let at=leagueTable[f.away.short];if(!ht||!at)return;ht.pld++;at.pld++;ht.gf+=hg;ht.ga+=ag;at.gf+=ag;at.ga+=hg;if(hg>ag){ht.w++;ht.pts+=3;at.l++;}else if(ag>hg){at.w++;at.pts+=3;ht.l++;}else{ht.d++;at.d++;ht.pts+=1;at.pts+=1;}});}
function s2r(s){let[h,a]=s.split('-').map(Number);if(h>a)return'home';if(a>h)return'away';return'draw';}
function pickFinalScore(chosen){if(chosen==='home'){let opts=['1-0','2-0','2-1','3-1','1-0'];return opts[Math.floor(Math.random()*opts.length)];}else if(chosen==='away'){let opts=['0-1','0-2','1-2','0-3','0-1'];return opts[Math.floor(Math.random()*opts.length)];}else{let opts=['0-0','1-1','2-2','1-1'];return opts[Math.floor(Math.random()*opts.length)];}}
function decideTargets(fixtures){let targets={};fixtures.forEach(f=>{let r=Math.random();let chosen=r<0.40?'home':r<0.75?'away':'draw';targets[f.id]=pickFinalScore(chosen);});return targets;}
function maybeGoalTowardsTarget(){if(!liveFixtures||!targetScores)return;if(Math.random()>0.20)return;let cands=liveFixtures.filter(f=>{let[h,a]=f.score.split('-').map(Number);let[th,ta]=targetScores[f.id].split('-').map(Number);return h<th||a<ta;});if(!cands.length)return;let f=cands[Math.floor(Math.random()*cands.length)];let[h,a]=f.score.split('-').map(Number);let[th,ta]=targetScores[f.id].split('-').map(Number);if(h<th&&a<ta){if(Math.random()<0.5)h++;else a++;}else if(h<th)h++;else if(a<ta)a++;f.score=h+'-'+a;f.result=s2r(f.score);}
setInterval(async()=>{
  virtualTimeLeft--;
  if(virtualPhase==='betting'&&virtualTimeLeft<=0){
    targetScores=decideTargets(currentFixtures);
    liveFixtures=currentFixtures.map(m=>({id:m.id,home:m.home,away:m.away,score:'0-0',result:'draw'}));
    virtualPhase='first_half';virtualTimeLeft=45;
  }else if(virtualPhase==='first_half'){maybeGoalTowardsTarget();if(virtualTimeLeft<=0){virtualPhase='halftime';virtualTimeLeft=5;}
  }else if(virtualPhase==='halftime'&&virtualTimeLeft<=0){virtualPhase='second_half';virtualTimeLeft=45;
  }else if(virtualPhase==='second_half'){
    maybeGoalTowardsTarget();
    if(virtualTimeLeft<=0){
      if(liveFixtures&&targetScores){
        liveFixtures.forEach(f=>{if(targetScores[f.id]){f.score=targetScores[f.id];f.result=s2r(f.score);}});
        try{if(db){
            let settlingMD=matchday+1;
            let[accas]=await db.query("SELECT * FROM virtual_accas WHERE season=? AND matchday=? AND status='pending'",[season,settlingMD]);
            updateTable(liveFixtures);
            pastResults.unshift({matchday:settlingMD,season,fixtures:liveFixtures.map(ff=>({...ff})),time:new Date().toLocaleTimeString(),ts:Date.now()});
            if(pastResults.length>20)pastResults.pop();
            for(let a of accas){
              let sels=[];try{sels=JSON.parse(a.selections);}catch(e){sels=[];}
              let win=true;for(let s of sels){let mf=liveFixtures.find(x=>x.id==s.matchId);if(!mf||mf.result!==s.prediction){win=false;break;}}
              if(win){let wa=Math.floor(a.amount*a.odd);await db.query("UPDATE virtual_accas SET status='won', winAmount=? WHERE id=?",[wa,a.id]);await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[wa,a.userId]);}
              else{await db.query("UPDATE virtual_accas SET status='lost' WHERE id=?",[a.id]);}
            }
          }}catch(e){}
      }
      matchday++;if(matchday>=15){season++;matchday=0;seasonSchedule=genSched();initTable();}
      currentFixtures=nextFixtures;nextFixtures=getFix(matchday+1);liveFixtures=null;targetScores=null;virtualPhase='betting';virtualTimeLeft=120;
    }
  }
},1000);

// ===== NEW GAMES LOGIC =====
let crashState={phase:'betting', mult:1.00, crashPoint:2.00, timeLeft:10, history:[]};
function newCrashPoint(){
  const r=Math.random();
  if(r<0.08) return (1.00+Math.random()*0.2).toFixed(2); // 8% instant
  if(r<0.30) return (1.10+Math.random()*0.9).toFixed(2); // low
  return ( (1.5 + Math.random()*8).toFixed(2) ); // 70% up to 9.5x
}
setInterval(()=>{ // CRASH CYCLE 25 sec
  if(crashState.phase==='betting'){
    crashState.timeLeft--;
    if(crashState.timeLeft<=0){crashState.phase='flying';crashState.mult=1.00;crashState.crashPoint=parseFloat(newCrashPoint());}
  }else if(crashState.phase==='flying'){
    crashState.mult=parseFloat((crashState.mult+0.04+crashState.mult*0.02).toFixed(2));
    if(crashState.mult>=crashState.crashPoint){crashState.phase='crashed';crashState.timeLeft=5;crashState.history.unshift(crashState.crashPoint);if(crashState.history.length>15)crashState.history.pop();}
  }else if(crashState.phase==='crashed'){
    crashState.timeLeft--;
    if(crashState.timeLeft<=0){crashState.phase='betting';crashState.timeLeft=10;crashState.mult=1.00;}
  }
},200);

// DB CONNECT - AIVEN SSL FIX
(async()=>{try{
  const u=(process.env.DATABASE_URL||process.env.MYSQL_URL||"").trim();
  if(!u){console.log("NO DB URL");return;}
  console.log("Connecting Aiven...");
  const parsed=new URL(u);
  db=mysql.createPool({
    host:parsed.hostname, user:parsed.username, password:decodeURIComponent(parsed.password),
    database:parsed.pathname.replace("/","").split("?")[0]||"defaultdb", port:parsed.port||19073,
    ssl:{rejectUnauthorized:false}, waitForConnections:true, connectionLimit:10, enableKeepAlive:true
  });
  await db.query("SELECT 1"); console.log("DB CONNECTED OK");
  await db.query("CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, fullName VARCHAR(100), phone VARCHAR(30), password VARCHAR(100), withdrawPassword VARCHAR(100), myReferralCode VARCHAR(20), referredBy VARCHAR(20), balance INT DEFAULT 0, gameBalance INT DEFAULT 0)");
  await db.query("CREATE TABLE IF NOT EXISTS deposits (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, phone VARCHAR(30), amount INT, airtelNo VARCHAR(30), screenshot LONGTEXT, screenshotHash VARCHAR(100), status VARCHAR(20) DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  await db.query("CREATE TABLE IF NOT EXISTS investments (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, club VARCHAR(50), amount INT, rate INT, lockDays INT, profitPaid INT DEFAULT 0, startDate DATETIME DEFAULT CURRENT_TIMESTAMP, status VARCHAR(20) DEFAULT 'active')");
  await db.query("CREATE TABLE IF NOT EXISTS virtual_accas (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, season INT, matchday INT, selections TEXT, amount INT, odd FLOAT, status VARCHAR(20) DEFAULT 'pending', winAmount INT DEFAULT 0, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  await db.query("CREATE TABLE IF NOT EXISTS withdrawals (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, phone VARCHAR(30), amount INT, status VARCHAR(20) DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  await db.query("CREATE TABLE IF NOT EXISTS crash_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, cashoutAt FLOAT, crashAt FLOAT, status VARCHAR(20), win INT, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  await db.query("CREATE TABLE IF NOT EXISTS wheel_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, mult FLOAT, win INT, status VARCHAR(20), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  await db.query("CREATE TABLE IF NOT EXISTS dice_bets (id INT AUTO_INCREMENT PRIMARY KEY, userId INT, amount INT, roll INT, target INT, type VARCHAR(10), win INT, status VARCHAR(20), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP)");
  console.log("DB ok - WITH ALL GAMES");tg("✅ <b>LIFELINE + 3 GAMES LIVE</b>");
}catch(e){console.log("DB ERROR:",e.message)}})();

