const crashPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px;padding-bottom:90px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px;z-index:10}.plane{font-size:80px;text-align:center;margin:30px 0 10px;transition:transform 0.2s}.mult{font-size:64px;font-weight:900;text-align:center;color:#0f0}.mult.crashed{color:#f44}.hist{display:flex;gap:6px;overflow:auto;padding:8px 0}.hist span{padding:4px 8px;border-radius:12px;font-size:12px;font-weight:900;background:#222;color:#0f0}.hist span.low{background:#331111;color:#f44}.card{background:#111;border:1px solid gold;border-radius:16px;padding:14px;margin:10px 0}button{width:100%;padding:16px;border-radius:12px;border:none;font-weight:900;font-size:16px}input{width:100%;padding:14px;border-radius:12px;border:1px solid gold;background:#000;color:#fff;margin:8px 0}</style></head><body><div class='top'>CRASH AVIATOR • <span id='phase'>BETTING</span></div><a href='/dashboard' style='color:gold;margin-top:50px;display:inline-block'>← Back</a><div class='plane' id='plane'>✈️</div><div class='mult' id='mult'>1.00x</div><div style='text-align:center;font-size:12px;color:#aaa' id='timer'>Betting: 10s</div><div class='hist' id='hist'></div><div class='card'><div style='display:flex;justify-content:space-between'><span>WALLET</span><b id='bal' style='color:gold'>0</b></div><input id='amt' type='number' value='1000' min='500'><div style='display:flex;gap:8px'><button id='betBtn' onclick='place()' style='background:gold;color:#000'>PLACE BET</button><button id='cashBtn' onclick='cashout()' style='background:#0f0;color:#000;display:none'>CASHOUT</button></div><div id='msg' style='text-align:center;margin-top:8px;font-size:13px'></div></div><script>let uid=localStorage.getItem('uid');let myBet=null;let myCash=false;async function loadBal(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent=((u.balance||0)+(u.gameBalance||0)).toLocaleString()+' UGX';}async function sync(){let r=await fetch('/api/games/crash/status');let d=await r.json();phase.textContent=d.phase.toUpperCase();mult.textContent=d.mult.toFixed(2)+'x';mult.className='mult '+(d.phase==='crashed'?'crashed':'');timer.textContent=d.phase==='betting'?'Betting: '+d.timeLeft+'s':d.phase==='flying'?'Flying...':'CRASHED @ '+d.crashPoint+'x';plane.style.transform=d.phase==='flying'?'translate('+d.mult*3+'px,-'+d.mult*2+'px) rotate(20deg)':'translate(0,0)';hist.innerHTML=(d.history||[]).map(x=>'<span class='+(x<1.2?'low':'')+'>'+x+'x</span>').join('');if(d.phase==='betting'){betBtn.style.display='block';if(!myBet)cashBtn.style.display='none';}else if(d.phase==='flying'&&myBet&&!myCash){betBtn.style.display='none';cashBtn.style.display='block';cashBtn.textContent='CASHOUT '+(d.mult*myBet.amount).toFixed(0)+' UGX @ '+d.mult+'x';}else if(d.phase==='crashed'){betBtn.style.display='block';cashBtn.style.display='none';if(myBet&&!myCash){msg.textContent='💥 CRASHED - Lost '+myBet.amount;myBet=null;myCash=false;loadBal();}if(!myBet){/*reset*/}}}async function place(){let a=parseInt(amt.value);if(a<500)return alert('Min 500');let r=await fetch('/api/games/crash/bet',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a})});let j=await r.json();if(j.ok){myBet={amount:a};myCash=false;msg.textContent='Bet placed '+a+' - wait flying';loadBal();}else alert(j.error);}async function cashout(){if(!myBet||myCash)return;myCash=true;let r=await fetch('/api/games/crash/cashout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid})});let j=await r.json();if(j.ok){msg.textContent='✅ WON '+j.win+' @ '+j.mult+'x';myBet=null;myCash=false;loadBal();}else{msg.textContent=j.error;}}loadBal();setInterval(sync,200);<\/script></body></html>";

const wheelPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px}.wheel{width:220px;height:220px;border-radius:50%;border:8px solid gold;margin:60px auto 20px;position:relative;background:conic-gradient(#111 0deg 45deg,#222 45deg 90deg,#0a0a0a 90deg 135deg,#333 135deg 180deg,#111 180deg 225deg,#222 225deg 270deg,#0a0a0a 270deg 315deg,gold 315deg 360deg);display:flex;align-items:center;justify-content:center;font-size:48px;transition:transform 3s cubic-bezier(0.2,0.8,0.2,1)}.card{background:#111;border:1px solid gold;border-radius:16px;padding:14px}input,button{width:100%;padding:14px;border-radius:12px;border:none;margin:6px 0}button{background:gold;font-weight:900}input{background:#000;color:#fff;border:1px solid gold}</style></head><body><div class='top'>WHEEL SPIN • 50x</div><a href='/dashboard' style='color:gold;margin-top:40px;display:inline-block'>← Back</a><div class='wheel' id='wheel'>🎡</div><div style='text-align:center'><b id='res' style='font-size:28px;color:gold'>-</b><div id='bal'>Balance: 0</div></div><div class='card'><input id='amt' type='number' value='1000' min='500' placeholder='Bet 500 min'><button onclick='spin()'>SPIN WHEEL</button><div id='msg' style='text-align:center;margin-top:8px'></div></div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent='Balance: '+((u.balance||0)+(u.gameBalance||0)).toLocaleString();}async function spin(){let a=parseInt(amt.value);if(a<500)return alert('Min 500');wheel.style.transform='rotate('+(720+Math.random()*720)+'deg)';let r=await fetch('/api/games/wheel/spin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a})});let j=await r.json();setTimeout(()=>{res.textContent=j.mult+'x';msg.innerHTML=j.win>0?'<span style=color:#0f0>✅ WON '+j.win+'</span>':'<span style=color:#f44>❌ LOST - 0x</span>';load();},2500);}load();<\/script></body></html>";

const dicePage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);background:#000;border:1px solid gold;padding:6px 16px;border-radius:20px;color:gold;font-size:11px}.dice{font-size:90px;text-align:center;margin:50px 0 10px}.card{background:#111;border:1px solid gold;border-radius:16px;padding:14px;margin:8px 0}input,button,select{width:100%;padding:14px;border-radius:12px;border:none;margin:6px 0}button{background:gold;font-weight:900}input,select{background:#000;color:#fff;border:1px solid gold}</style></head><body><div class='top'>DICE • Over/Under</div><a href='/dashboard' style='color:gold;margin-top:40px;display:inline-block'>← Back</a><div class='dice' id='dice'>🎲</div><div style='text-align:center'><b id='roll' style='font-size:36px;color:gold'>-</b><div id='bal'>Balance: 0</div></div><div class='card'><label>Target 1-99</label><input id='target' type='number' value='50' min='2' max='98'><select id='type'><option value='over'>Over</option><option value='under'>Under</option></select><input id='amt' type='number' value='1000' min='500'><button onclick='rollDice()'>ROLL DICE</button><div id='msg' style='text-align:center;margin-top:8px'></div></div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent='Balance: '+((u.balance||0)+(u.gameBalance||0)).toLocaleString();}async function rollDice(){let a=parseInt(amt.value),t=parseInt(target.value),ty=type.value;if(a<500)return alert('Min 500');let r=await fetch('/api/games/dice/roll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,target:t,type:ty})});let j=await r.json();dice.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][Math.floor(j.roll%6)];roll.textContent=j.roll;j.win>0?msg.innerHTML='<span style=color:#0f0>✅ WON '+j.win+' (roll '+j.roll+')</span>':msg.innerHTML='<span style=color:#f44>❌ LOST (roll '+j.roll+')</span>';load();}load();<\/script></body></html>";

