const depositPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px;padding-bottom:90px}.glass{background:rgba(18,22,35,0.9);border:1px solid rgba(255,215,0,0.15);border-radius:16px;padding:16px}.top{position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:10;background:rgba(0,0,0,0.8);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px;font-weight:900}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none;box-sizing:border-box}button{background:gold;font-weight:900}.merchantBox{background:linear-gradient(135deg,#1a1a00,#2a2a00);border:2px solid gold;border-radius:16px;padding:18px;margin:14px 0;text-align:center}.merchantCode{font-size:42px;font-weight:900;color:gold;letter-spacing:2px}</style></head><body><div class='top'>DEPOSIT • 7184154</div><a href='/dashboard' style='color:gold;margin-top:60px;display:inline-block;text-decoration:none'>← Back</a><div class='merchantBox'><div style='font-size:11px;color:#aaa'>AIRTEL MONEY • MERCHANT CODE</div><div class='merchantCode' id='mcode'>7184154</div><button onclick='copyCode()' style='width:auto;background:#fff;color:#000;padding:8px 16px;border-radius:20px'>COPY</button></div><div class='glass'><label>AMOUNT YOU PAID (UGX)</label><input id='am' type='number' placeholder='e.g 10000'><label>YOUR AIRTEL NUMBER USED</label><input id='air' placeholder='0700 123456'><input type='file' id='file' accept='image/*'><div id='preview'></div><button onclick='dep()' id='b'>✅ Submit Deposit</button><div id='msg'></div></div><script>let uid=localStorage.getItem('uid');let b64='',h='';file.addEventListener('change',e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{b64=r.result;h=Date.now()+'_'+f.size;preview.innerHTML='<img src=\"'+b64+'\" style=\"max-width:100%;border-radius:12px;max-height:200px\">';};r.readAsDataURL(f);});async function dep(){let a=am.value.trim(),air=document.getElementById('air').value.trim();if(!a||!air||!b64)return msg.textContent='Fill all';b.disabled=true;let res=await fetch('/api/deposit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:parseInt(a),airtelNo:air,screenshot:b64,screenshotHash:h})});let j=await res.json();msg.textContent=j.ok?'✅ Submitted!':'❌ '+(j.error||'Failed');if(j.ok)setTimeout(()=>location.href='/dashboard',1200);else b.disabled=false;}\<\/script></body></html>";
const investPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{margin:0;padding:0;background:#0a0e1a;color:#fff;font-family:Arial;padding-bottom:90px}.top{position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:10;background:rgba(0,0,0,0.7);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px}.hdr{margin-top:60px;padding:16px}.clubGrid{display:grid;grid-template-columns:1fr;gap:12px;padding:0 12px}.clubCard{background:linear-gradient(135deg,rgba(255,255,255,0.08),rgba(255,255,255,0.02));border:1px solid rgba(255,215,0,0.2);border-radius:20px;padding:16px}.amtInput{flex:1;background:#000;border:1px solid gold;border-radius:12px;padding:12px;color:#fff}.invBtn{width:90px;background:gold;color:#000;font-weight:900;border-radius:12px;border:none;cursor:pointer}.inputRow{display:flex;gap:8px;margin-top:12px}.myInv{background:#111;border-left:4px solid gold;padding:12px;margin:8px 12px;border-radius:10px}</style></head><body><div class='top'>INVEST • Earn 10% Daily</div><div class='hdr'><h2>💎 Premium Football Investments</h2><a href='/dashboard' style='color:gold'>← Back</a></div><div id='clubs' class='clubGrid'></div><div id='myInvSec'><h3 style='color:gold;padding:0 12px'>📈 My Active Investments</h3><div id='myList'>Loading...</div></div><script>let uid=localStorage.getItem('uid');const C=[{id:'arsenal',name:'Arsenal',rate:10,icon:'ARS',color:'#EF0107'},{id:'mancity',name:'Man City',rate:10,icon:'MCI',color:'#6CABDD'},{id:'liverpool',name:'Liverpool',rate:10,icon:'LIV',color:'#C8102E'}];clubs.innerHTML=C.map(c=>'<div class=clubCard><div style=\"display:flex;gap:12px\"><div style=\"width:48px;height:48px;border-radius:12px;background:'+c.color+';color:#fff;display:flex;align-items:center;justify-content:center;font-weight:900\">'+c.icon+'</div><div><b>'+c.name+'</b><div style=\"font-size:11px;color:#aaa\">'+c.rate+'% daily for 10 days</div></div></div><div class=inputRow><input id=\"amt_'+c.id+'\" class=amtInput type=number placeholder=\"Amount Min 2000\"><button class=invBtn onclick=\"investClub(\\''+c.id+'\\')\">INVEST</button></div></div>').join('');async function investClub(club){let a=document.getElementById('amt_'+club).value;if(!a||parseInt(a)<2000)return alert('Min 2000');let r=await fetch('/api/invest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,club,amount:parseInt(a)})});let j=await r.json();if(j.ok){alert('Invested');loadMy();}else alert(j.error);}async function loadMy(){let r=await fetch('/api/investments/'+uid);let data=await r.json();if(!data.length){myList.innerHTML='<div style=\"padding:12px;color:#888\">No investments yet</div>';return;}myList.innerHTML=data.map(inv=>'<div class=myInv><b>'+inv.club.toUpperCase()+'</b> '+inv.amount+' UGX - '+inv.status+'</div>').join('');}loadMy();<\/script></body></html>";
const virtualPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{margin:0;padding:0;padding-bottom:140px;background:#111;color:#fff;font-family:Arial}.top{position:fixed;top:10px;left:50%;transform:translateX(-50%);z-index:20;background:rgba(0,0,0,0.85);border:1px solid gold;padding:5px 16px;border-radius:20px;color:gold;font-size:11px}.tabPill{display:flex;background:#222;border-radius:30px;padding:5px;margin:60px 12px 10px;gap:3px}.tab{flex:1;padding:10px;text-align:center;border-radius:20px;font-size:11px;color:#888;font-weight:900}.tab.active{background:#3a3a3a;color:#fff}.match{background:#2a2a2a;margin:8px 12px;border-radius:14px;padding:12px}.odd{flex:1;background:#3a3a3a;border-radius:8px;padding:10px;display:flex;justify-content:space-between;cursor:pointer}.odd.sel{background:#1a3d1a;border-color:#0f0}.bar{position:fixed;bottom:0;left:0;right:0;background:#b2ff00;color:#000;padding:14px;display:flex;justify-content:space-between;font-weight:900;z-index:99}.sheet{position:fixed;bottom:0;left:0;right:0;background:#1e1e1e;max-height:85vh;overflow:auto;display:none;padding:14px;border-top:2px solid gold;z-index:100}</style></head><body><div class='top'>MD <span id='topMD'>0</span> • 1.5/1.9/1.8</div><div class='tabPill'><div id='tabLive' class='tab active' onclick=\"switchTab('live')\">Live</div><div id='tabNext' class='tab' onclick=\"switchTab('next')\">Next</div><div id='tabBets' class='tab' onclick=\"switchTab('bets')\">My Bets</div></div><div id='liveSec'><div style='padding:0 12px;font-size:11px;display:flex;justify-content:space-between'><span id='phaseInfo'>BETTING</span><span id='timerTop' style='color:#ff6b00;font-weight:900'>02:00</span></div><div id='list'>Loading</div></div><div id='nextSec' style='display:none'><div id='nextList'></div></div><div id='betsSec' style='display:none'><div id='myBetsList' style='padding:12px'></div></div><div class='bar' onclick='openS()'><span>🎫 MD <span id='betMD'>0</span> <span id='oddShow'>0.00</span>x</span><span id='lc'>0 legs</span></div><div class='sheet' id='sheet'><h3 style='color:gold'>Betslip <span id='sc'>0</span> - Odd <span id='oddDetail'>0</span></h3><div id='sl'></div><input id='amt' type='number' value='500' min='500' max='5000' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid gold;border-radius:10px;margin:8px 0'><button onclick='place()' style='width:100%;padding:12px;background:gold'>Place Bet</button><button onclick='closeS()' style='width:100%;padding:10px;background:#222;color:#fff;margin-top:8px'>Close</button></div><script>let sel=[],currentBetMD=0,uid=localStorage.getItem('uid'),ODDS={home:1.5,draw:1.9,away:1.8};function switchTab(t){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.getElementById('tab'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');liveSec.style.display=t==='live'?'block':'none';nextSec.style.display=t==='next'?'block':'none';betsSec.style.display=t==='bets'?'block':'none';if(t==='bets')loadBets();}function calcOdd(){if(!sel.length)return 0;let o=1;sel.forEach(s=>{o*=ODDS[s.prediction]||1.5;});return (o*0.90).toFixed(2);}function tog(id,hs,as,p,md){let phaseTxt=(document.getElementById('phaseInfo').textContent||'');if(!phaseTxt.includes('BETTING')){alert('BETTING CLOSED');return;}let ex=sel.findIndex(s=>s.matchId===id);if(ex!==-1){if(sel[ex].prediction===p)sel.splice(ex,1);else sel[ex].prediction=p;}else{if(sel.length>=5)return alert('Max 5 legs');sel.push({matchId:id,homeShort:hs,awayShort:as,prediction:p,md});}currentBetMD=md;rend();}function rend(){document.querySelectorAll('.odd').forEach(b=>b.classList.remove('sel'));sel.forEach(s=>{let e=document.querySelector('[data-m=\"'+s.matchId+'\"][data-p=\"'+s.prediction+'\"]');if(e)e.classList.add('sel');});sc.textContent=sel.length;let co=calcOdd();oddShow.textContent=co;oddDetail.textContent=co;lc.textContent=sel.length+' legs';betMD.textContent=currentBetMD||topMD.textContent;sl.innerHTML=sel.map(s=>'<div style=\"background:#2a2a2a;padding:6px;margin:3px 0;display:flex;justify-content:space-between\"><span>MD'+s.md+' '+s.homeShort+'-'+s.awayShort+' '+s.prediction+' @'+ODDS[s.prediction]+'</span><span onclick=\"remSel('+s.matchId+')\" style=\"color:red\">✕</span></div>').join('')||'Tap odds';}function remSel(id){sel=sel.filter(s=>s.matchId!==id);rend();}function openS(){sheet.style.display='block';}function closeS(){sheet.style.display='none';}async function place(){if(!sel.length)return alert('Add');let a=parseInt(amt.value);if(a<500||a>5000)return alert('500-5000 only');let r=await fetch('/api/virtual/bet/acca',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,selections:sel.map(s=>({matchId:s.matchId,homeTeam:s.homeShort,awayTeam:s.awayShort,prediction:s.prediction,md:s.md})),betMD:currentBetMD})});let j=await r.json();if(j.ok){alert('Placed');sel=[];rend();closeS();switchTab('bets');}else alert(j.error);}async function loadBets(){let r=await fetch('/api/virtual/my-bets/'+uid);let d=await r.json();myBetsList.innerHTML=d.slice(0,20).map(b=>'<div style=\"background:#fff;color:#000;padding:8px;margin:6px 0;border-radius:8px;border-left:4px solid '+(b.status==='won'?'#0f0':b.status==='lost'?'#f44':'#000')+'\">MD'+b.matchday+' '+b.amount+'x'+b.odd+' '+b.status.toUpperCase()+' '+(b.winAmount||'')+'</div>').join('')||'No bets';}async function sync(){let r=await fetch('/api/virtual/status');let d=await r.json();topMD.textContent=d.matchday;let tl=d.timeLeft;let disp=Math.floor(tl/60)+':'+String(tl%60).padStart(2,'0');if(d.phase!=='betting'){if(d.phase==='first_half')disp='00:'+(45-tl);else if(d.phase==='halftime')disp='00:0'+tl;else{let tot=45+(45-tl);disp=String(Math.floor(tot/60)).padStart(2,'0')+':'+String(tot%60).padStart(2,'0');}}timerTop.textContent=disp;phaseInfo.textContent=d.phase.toUpperCase()+' MD'+d.matchday;let fix=d.phase==='betting'?d.currentFixtures:d.allLive;let h='';(fix||[]).forEach(m=>{let isLive=d.phase!=='betting';h+='<div class=\"'+(isLive?'match live':'match')+'\"><div style=\"display:flex;justify-content:space-between\"><span style=\"font-weight:900\">'+m.home.short+' - '+m.away.short+'</span>'+(isLive?'<span style=\"background:#0f0;color:#000;padding:4px 10px;border-radius:20px\">LIVE '+m.score+'</span>':'<span style=\"background:#ffcc00;color:#000;padding:4px 10px;border-radius:20px\">BETTING</span>')+'</div><div style=\"display:flex;gap:5px;margin-top:10px;'+(isLive?'opacity:0.3;pointer-events:none':'')+'\"><div class=odd data-m=\"'+m.id+'\" data-p=\"home\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'home\\','+d.matchday+')\"><span>1</span><span>1.5</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"draw\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'draw\\','+d.matchday+')\"><span>X</span><span>1.9</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"away\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'away\\','+d.matchday+')\"><span>2</span><span>1.8</span></div></div></div>';});list.innerHTML=h;let h2='';(d.nextFixtures||[]).forEach(m=>{h2+='<div class=match><span>'+m.home.short+' - '+m.away.short+'</span></div>';});nextList.innerHTML=h2;if(currentBetMD===0)currentBetMD=d.phase==='betting'?d.matchday:d.nextMD;}sync();setInterval(sync,1000);<\/script></body></html>";
const withdrawPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none;box-sizing:border-box}button{background:gold;font-weight:bold}.card{background:rgba(18,22,35,0.9);padding:16px;border-radius:16px;border:1px solid #0f0}</style></head><body><a href='/dashboard' style='color:gold;margin-top:10px;display:inline-block'>← Back</a><h2>Withdraw BALANCE</h2><div class='card'><div id='bal' style='font-size:28px;color:#0f0;font-weight:900'>0</div><input id='am' type='number' placeholder='Min 5000'><input id='ph' placeholder='Airtel number'><input id='wpw' type='password' placeholder='Withdraw Password'><button onclick='wd()'>Withdraw</button><div id='msg'></div></div><div id='wlist'></div><script>let uid=localStorage.getItem('uid');async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent=(u.gameBalance||0).toLocaleString()+' UGX';let r2=await fetch('/api/withdrawals/'+uid);let d=await r2.json();wlist.innerHTML=d.map(x=>'<div style=\"background:#1a1a1a;padding:8px;margin:4px 0\">'+x.amount+' to '+x.phone+' '+x.status+'</div>').join('');}async function wd(){let a=parseInt(am.value),ph=document.getElementById('ph').value,wpw=document.getElementById('wpw').value;if(a<5000)return msg.textContent='Min 5k';if(!wpw)return msg.textContent='Enter withdraw password';let r=await fetch('/api/withdraw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,phone:ph,withdrawPassword:wpw})});let j=await r.json();msg.textContent=j.ok?'Sent - Awaiting approval':j.error;load();}load();<\/script></body></html>";
