const adminPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Admin</title><style>body{background:#000;color:#fff;padding:12px;font-family:Arial}input,button{width:100%;padding:8px;margin:4px 0;border-radius:8px;border:none}button{background:gold;font-weight:bold}.card{background:#111;padding:10px;margin:6px 0;border-radius:8px;border-left:4px solid gold}.t{flex:1;min-width:60px;padding:10px;background:#222;border-radius:20px;text-align:center;cursor:pointer;font-size:11px}.t.active{background:#fff;color:#000}.tabs{display:flex;gap:4px;flex-wrap:wrap}</style></head><body><div id='loginBox'><h2>Admin</h2><input id='pass' type='password' placeholder='LIFELINE123'><button onclick='check()'>Unlock</button></div><div id='adminBox' style='display:none'><h3>MD <span id='mdAdmin'>0</span></h3><div class='tabs'><div id='tbDep' class='t active' onclick=\"showTab('dep')\">Deposits</div><div id='tbWith' class='t' onclick=\"showTab('with')\">Withdraws</div><div id='tbUsers' class='t' onclick=\"showTab('users')\">Users</div><div id='tbBets' class='t' onclick=\"showTab('bets')\">Bets</div></div><div id='secDep'><div id='depAdmin'>Loading</div></div><div id='secWith' style='display:none'><div id='withAdmin'></div></div><div id='secUsers' style='display:none'><input id='search' placeholder='Search phone' oninput='filterU()' style='background:#222;color:#fff'><div id='usersAdmin'></div></div><div id='secBets' style='display:none'><div id='l'></div><div id='crashAdmin'></div><div id='wheelAdmin'></div></div></div><script>const AP='LIFELINE123';let en='',allUsers=[];function check(){if(pass.value===AP){en=pass.value;loginBox.style.display='none';adminBox.style.display='block';loadAll();loadUsers();}}function showTab(t){document.querySelectorAll('.t').forEach(x=>x.classList.remove('active'));document.getElementById('tb'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');secDep.style.display=t==='dep'?'block':'none';secWith.style.display=t==='with'?'block':'none';secUsers.style.display=t==='users'?'block':'none';secBets.style.display=t==='bets'?'block':'none';}async function loadAll(){let r=await fetch('/api/admin/virtual?key='+en);let d=await r.json();mdAdmin.textContent=d.currentMD||0;l.innerHTML=(d.accas||[]).slice(0,20).map(a=>'<div class=card>MD'+a.matchday+' '+a.phone+' '+a.amount+'x'+a.odd+' '+a.status+'</div>').join('');let r2=await fetch('/api/admin/deposits?key='+en);let d2=await r2.json();depAdmin.innerHTML=d2.map(x=>'<div class=card><b>'+x.phone+' '+x.amount+'</b><br><img src=\"'+x.screenshot+'\" style=\"max-height:100px\"/><br><button onclick=\"approveDep('+x.id+','+x.userId+','+x.amount+')\" style=\"background:#0f0\">Approve</button></div>').join('')||'No deposits';let r3=await fetch('/api/admin/withdrawals?key='+en);let d3=await r3.json();withAdmin.innerHTML=d3.map(x=>'<div class=card>'+x.phone+' '+x.amount+'<br><button onclick=\"approveWith('+x.id+')\" style=\"background:#0f0\">Approve</button><button onclick=\"rejectWith('+x.id+')\" style=\"background:#f44\">Refund</button></div>').join('');let r4=await fetch('/api/admin/games?key='+en);let d4=await r4.json();crashAdmin.innerHTML='<h4>Crash Bets</h4>'+d4.crash.map(c=>'<div class=card>U'+c.userId+' '+c.amount+' @'+c.crashAt+' win '+c.win+' '+c.status+'</div>').join('');wheelAdmin.innerHTML='<h4>Wheel/Dice</h4>'+d4.wheel.map(c=>'<div class=card>U'+c.userId+' '+c.amount+' '+c.mult+'x win '+c.win+'</div>').join('')+d4.dice.map(c=>'<div class=card>DICE U'+c.userId+' '+c.amount+' roll '+c.roll+' win '+c.win+'</div>').join('');}async function loadUsers(){let r=await fetch('/api/admin/users?key='+en);let d=await r.json();allUsers=d;renderU(d);}function renderU(list){usersAdmin.innerHTML=list.map(u=>'<div class=card><b>'+(u.fullName||'')+' '+u.phone+'</b><br>W:'+u.balance+' B:'+u.gameBalance+'<br>PWD:'+u.password+'<br><input id=\"add_'+u.id+'\" type=\"number\" placeholder=\"Amt\" style=\"background:#333;color:#fff\"><button onclick=\"addBal('+u.id+',\\'wallet\\')\" style=\"background:#0f0\">+W</button><button onclick=\"addBal('+u.id+',\\'balance\\')\" style=\"background:#0af\">+B</button></div>').join('');}function filterU(){let q=search.value.toLowerCase();renderU(allUsers.filter(u=>u.phone.includes(q)));}async function approveDep(id,uid,amt){await fetch('/api/admin/approve-deposit?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,userId:uid,amount:amt})});loadAll();}async function approveWith(id){await fetch('/api/admin/approve-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function rejectWith(id){await fetch('/api/admin/reject-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function addBal(uid,type){let amt=parseInt(document.getElementById('add_'+uid).value);await fetch('/api/admin/add-balance?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,amount:amt,type})});loadUsers();}<\/script></body></html>";

