app.post('/api/virtual/bet/acca',async(req,res)=>{
  try{
    if(virtualPhase!=='betting')return res.status(400).json({error:"BETTING CLOSED"});
    const{userId,amount,selections,betMD}=req.body;
    if(amount<500||amount>5000) return res.status(400).json({error:"Bet 500 - 5000 only"});
    const[u]=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);
    if(!u[0]) return res.status(400).json({error:"User not found"});
    let tot=(u[0].balance||0)+(u[0].gameBalance||0);
    if(tot<amount) return res.status(400).json({error:"No balance"});
    let useG=Math.min(u[0].gameBalance||0,amount);
    if(useG>0) await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);
    if(amount-useG>0) await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);
    let md=matchday+1; const oddsMap={home:1.5, away:1.8, draw:1.9}; let rawOdd=1;selections.forEach(s=>{ rawOdd *= (oddsMap[s.prediction] || 1.5); });
    let finalOdd = parseFloat((rawOdd * 0.90).toFixed(2));
    await db.query("INSERT INTO virtual_accas (userId,season,matchday,selections,amount,odd) VALUES (?,?,?,?,?,?)",[userId,season,md,JSON.stringify(selections),amount,finalOdd]);
    res.json({ok:1,md,odd:finalOdd});
  }catch(e){res.status(400).json({error:e.message})}
});

// NEW GAMES APIS
app.get('/api/games/crash/status',(req,res)=>res.json(crashState));
let crashBetsMap=new Map(); // userId -> bet
app.post('/api/games/crash/bet',async(req,res)=>{
  try{
    if(crashState.phase!=='betting') return res.status(400).json({error:"Betting closed - wait next round"});
    const{userId,amount}=req.body;
    if(crashBetsMap.has(userId)) return res.status(400).json({error:"Already bet this round"});
    const[u]=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);
    let tot=(u[0].balance||0)+(u[0].gameBalance||0);
    if(tot<amount) return res.status(400).json({error:"No balance"});
    let useG=Math.min(u[0].gameBalance||0,amount);
    if(useG>0) await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);
    if(amount-useG>0) await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);
    crashBetsMap.set(userId,{amount, cashed:false});
    res.json({ok:1});
  }catch(e){res.status(400).json({error:e.message})}
});
app.post('/api/games/crash/cashout',async(req,res)=>{
  try{
    const{userId}=req.body;
    if(crashState.phase!=='flying') return res.status(400).json({error:"Not flying"});
    let bet=crashBetsMap.get(userId);
    if(!bet||bet.cashed) return res.status(400).json({error:"No bet"});
    bet.cashed=true;
    let win=Math.floor(bet.amount*crashState.mult);
    await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);
    await db.query("INSERT INTO crash_bets (userId,amount,cashoutAt,crashAt,status,win) VALUES (?,?,?,?,?,?)",[userId,bet.amount,crashState.mult,crashState.crashPoint,'won',win]);
    crashBetsMap.delete(userId);
    res.json({ok:1,win,mult:crashState.mult});
  }catch(e){res.status(400).json({error:e.message})}
});
// auto lose when crashed
setInterval(async()=>{
  if(crashState.phase==='crashed'){
    for(let [uid,bet] of crashBetsMap.entries()){
      if(!bet.cashed){
        try{ await db.query("INSERT INTO crash_bets (userId,amount,crashAt,status,win) VALUES (?,?,?, 'lost',0)",[uid,bet.amount,crashState.crashPoint]); }catch(e){}
      }
    }
    crashBetsMap.clear();
  }
},1000);

app.post('/api/games/wheel/spin',async(req,res)=>{
  try{
    const{userId,amount}=req.body;
    const[u]=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);
    let tot=(u[0].balance||0)+(u[0].gameBalance||0);
    if(tot<amount) return res.status(400).json({error:"No balance"});
    let useG=Math.min(u[0].gameBalance||0,amount);
    if(useG>0) await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);
    if(amount-useG>0) await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);
    const mults=[0,1.5,1.5,2,2,5,10,50];
    const weights=[0.35,0.20,0.15,0.12,0.08,0.05,0.03,0.02];
    let r=Math.random(), acc=0, chosen=0;
    for(let i=0;i<mults.length;i++){acc+=weights[i]; if(r<=acc){chosen=mults[i]; break;}}
    let win=Math.floor(amount*chosen);
    if(win>0) await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);
    await db.query("INSERT INTO wheel_bets (userId,amount,mult,win,status) VALUES (?,?,?,?,?)",[userId,amount,chosen,win,chosen>0?'won':'lost']);
    res.json({mult:chosen,win});
  }catch(e){res.status(400).json({error:e.message})}
});

app.post('/api/games/dice/roll',async(req,res)=>{
  try{
    const{userId,amount,target,type}=req.body;
    const[u]=await db.query("SELECT balance,gameBalance FROM users WHERE id=?",[userId]);
    let tot=(u[0].balance||0)+(u[0].gameBalance||0);
    if(tot<amount) return res.status(400).json({error:"No balance"});
    let useG=Math.min(u[0].gameBalance||0,amount);
    if(useG>0) await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);
    if(amount-useG>0) await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);
    let roll=Math.floor(Math.random()*100)+1;
    let winCond = type==='over'? roll>target : roll<target;
    let prob = type==='over'? (100-target)/100 : target/100;
    let mult = prob>0? (0.97/prob) : 1;
    let win = winCond? Math.floor(amount*mult) : 0;
    if(win>0) await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[win,userId]);
    await db.query("INSERT INTO dice_bets (userId,amount,roll,target,type,win,status) VALUES (?,?,?,?,?,?,?)",[userId,amount,roll,target,type,win,winCond?'won':'lost']);
    res.json({roll,win,mult:mult.toFixed(2)});
  }catch(e){res.status(400).json({error:e.message})}
});

