app.post('/api/register',async(req,res)=>{try{const code='LIFE'+Math.random().toString(36).slice(2,5).toUpperCase()+Math.floor(Math.random()*9);const ref=req.body.referredBy||'';await db.query("INSERT INTO users (fullName,phone,password,withdrawPassword,myReferralCode,referredBy,balance,gameBalance) VALUES (?,?,?,?,?,?,0,0)",[req.body.name,req.body.phone,req.body.password,req.body.withdrawPassword,code,ref]);const[r]=await db.query("SELECT * FROM users WHERE phone=? ORDER BY id DESC LIMIT 1",[req.body.phone]);res.json(r[0]);}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/login',async(req,res)=>{try{const[r]=await db.query("SELECT * FROM users WHERE phone=? AND password=?",[req.body.phone,req.body.password]);if(r.length)res.json(r[0]);else res.status(401).json({error:"Wrong"});}catch(e){res.status(401).json({error:"Wrong"})}});
app.post('/api/deposit',async(req,res)=>{try{const{userId,amount,airtelNo,screenshot,screenshotHash}=req.body;const[u]=await db.query("SELECT phone FROM users WHERE id=?",[userId]);await db.query("INSERT INTO deposits (userId,phone,amount,airtelNo,screenshot,screenshotHash) VALUES (?,?,?,?,?,?)",[userId,u[0].phone,amount,airtelNo,screenshot,screenshotHash]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/invest',async(req,res)=>{try{const{userId,club,amount}=req.body;const[u]=await db.query("SELECT balance FROM users WHERE id=?",[userId]);if(!u[0]||u[0].balance<amount)return res.status(400).json({error:"No WALLET"});await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO investments (userId,club,amount,rate,lockDays) VALUES (?,?,?,?,?)",[userId,club,amount,10,10]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/withdraw',async(req,res)=>{try{const{userId,amount,phone,withdrawPassword}=req.body;const[u]=await db.query("SELECT gameBalance,withdrawPassword FROM users WHERE id=?",[userId]);if(u[0].withdrawPassword!==withdrawPassword)return res.status(400).json({error:"Wrong withdraw password"});if(u[0].gameBalance<amount)return res.status(400).json({error:"No BALANCE"});await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO withdrawals (userId,phone,amount) VALUES (?,?,?)",[userId,phone,amount]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/history/:id',async(req,res)=>{try{const[deps]=await db.query("SELECT amount,status,'deposit' as type FROM deposits WHERE userId=?",[req.params.id]);const[accas]=await db.query("SELECT amount,status,'acca' as type FROM virtual_accas WHERE userId=?",[req.params.id]);res.json([...deps,...accas]);}catch(e){res.json([]);}});
app.get('/api/team/:id',async(req,res)=>{try{const[u]=await db.query("SELECT myReferralCode FROM users WHERE id=?",[req.params.id]);const[team]=await db.query("SELECT phone,fullName FROM users WHERE referredBy=?",[u[0].myReferralCode]);res.json({team});}catch(e){res.json({team:[]})}});
app.get('/api/admin/deposits',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[rows]=await db.query("SELECT * FROM deposits WHERE status='pending' ORDER BY id DESC LIMIT 40");res.json(rows);});
app.get('/api/admin/withdrawals',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[rows]=await db.query("SELECT * FROM withdrawals WHERE status='pending' ORDER BY id DESC LIMIT 40");res.json(rows);});
app.get('/api/admin/users',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[rows]=await db.query("SELECT id,fullName,phone,password,withdrawPassword,balance,gameBalance,myReferralCode FROM users ORDER BY id DESC LIMIT 300");res.json(rows);});
app.get('/api/admin/games',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[c]=await db.query("SELECT * FROM crash_bets ORDER BY id DESC LIMIT 30");const[w]=await db.query("SELECT * FROM wheel_bets ORDER BY id DESC LIMIT 30");const[d]=await db.query("SELECT * FROM dice_bets ORDER BY id DESC LIMIT 30");res.json({crash:c,wheel:w,dice:d});});
app.post('/api/admin/approve-deposit',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE deposits SET status='approved' WHERE id=?",[req.body.id]);await db.query("UPDATE users SET balance=balance+? WHERE id=?",[req.body.amount,req.body.userId]);res.json({ok:1});});
app.post('/api/admin/approve-withdraw',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE withdrawals SET status='approved' WHERE id=?",[req.body.id]);res.json({ok:1});});
app.post('/api/admin/reject-withdraw',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});const[w]=await db.query("SELECT * FROM withdrawals WHERE id=?",[req.body.id]);if(w[0])await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[w[0].amount,w[0].userId]);await db.query("UPDATE withdrawals SET status='rejected' WHERE id=?",[req.body.id]);res.json({ok:1});});
app.post('/api/admin/add-balance',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});if(req.body.type==='wallet')await db.query("UPDATE users SET balance=balance+? WHERE id=?",[req.body.amount,req.body.id]);else await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[req.body.amount,req.body.id]);res.json({ok:1});});
app.get('/api/admin/virtual',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});const[r2]=await db.query("SELECT a.*,u.phone FROM virtual_accas a JOIN users u ON a.userId=u.id ORDER BY a.id DESC LIMIT 50");res.json({accas:r2,currentMD:matchday+1});});

const PORT=process.env.PORT||3000;
app.listen(PORT,()=>console.log("LIFELINE + 4 GAMES READY - "+PORT));
